#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { int renorm; int R; int split; int b; } Op;

static int range = 1;
static int cc[100000];
static Op *ops;
static int nops, capops;

static void addop(int renorm,int R,int split,int b){
  if(nops==capops){ capops=capops?capops*2:1024; ops=realloc(ops,capops*sizeof(Op)); if(!ops){fprintf(stderr,"oom\n");exit(1);} }
  ops[nops].renorm=renorm; ops[nops].R=R; ops[nops].split=split; ops[nops].b=b; nops++;
}

static void gb(int ctx,int b){
  if(range<255){ addop(1,range,0,0); range*=255; }
  int c0=cc[ctx*2], c1=cc[ctx*2+1];
  int split=(int)((long long)range*(c0+1)/(c0+c1+2));
  addop(0,range,split,b);
  range = b ? range-split : split;
  cc[ctx*2+b]++;
}

static void gi(int val,int tmp,int ctx){
  ctx*=99;
  int v=val+(1<<tmp);
  int L=0,t=v; while(t){L++;t>>=1;} L--;
  int j=L-tmp;
  if(j<0){fprintf(stderr,"bad gi val=%d tmp=%d\n",val,tmp);exit(1);}
  for(int k=1;k<=j;k++) gb(ctx+tmp+k,0);
  gb(ctx+tmp+j+1,1);
  for(int bb=L-1;bb>=0;bb--) gb(ctx,(v>>bb)&1);
}

static int floordiv(int a,int b){ int q=a/b; if((a%b!=0)&&((a<0)!=(b<0))) q--; return q; }
static int ceildiv(int a,int b){ int q=a/b; if((a%b!=0)&&((a<0)==(b<0))) q++; return q; }

int main(int argc,char**argv){
  const char*inf = argc>1?argv[1]:"data.txt";
  const char*outf= argc>2?argv[2]:"data.comp";
  FILE*f=fopen(inf,"rb"); if(!f){perror(inf);return 1;}
  static unsigned char data[100000];
  int n=fread(data,1,sizeof(data),f); fclose(f);
  for(int i=0;i<n;i++) if(data[i]==0){fprintf(stderr,"NUL in input\n");return 1;}

  /* token arrays */
  int *ttype=malloc(sizeof(int)*n), *tval=malloc(sizeof(int)*n);
  int nt=0, pos=0;
  while(pos<n){
    int maxL=0,bestD=0;
    for(int d=1;d<=pos;d++){
      int l=0, lim=n-pos;
      while(l<lim && data[pos+l]==data[pos+l-d]) l++;
      if(l>maxL){maxL=l;bestD=d;if(l==lim)break;}
    }
    int use=0;
    if(maxL>=3) use=1;
    else if(maxL==2 && bestD<=96) use=1;
    if(use){
      ttype[nt]=1; tval[nt]=bestD; nt++;
      ttype[nt]=2; tval[nt]=maxL; nt++;
      pos+=maxL;
    } else {
      ttype[nt]=0; tval[nt]=data[pos]; nt++;
      pos++;
    }
  }

