  int ntok=0;
  for(int i=0;i<nt;i++) if(ttype[i]!=2) ntok++;

  /* encode: number of tokens */
  gi(ntok,9,0);
  for(int i=0;i<nt;i++){
    if(ttype[i]==0){
      int c=tval[i];
      int sign = c<128?0:1;
      int mag = c<128?c:256-c;
      gb(8,sign);
      gi(mag,4,9);
    } else if(ttype[i]==1){
      int d=tval[i], l=tval[i+1];
      gb(1,1);
      gi(d-1,5,2);
      gi(l-1,2,3);
    }
  }

  /* backward feasible intervals for fraction */
  int N=nops;
  int *lo=malloc(sizeof(int)*(N+1)), *hi=malloc(sizeof(int)*(N+1));
  lo[N]=0; hi[N]=range-1;
  for(int i=N-1;i>=0;i--){
    Op o=ops[i]; int A=lo[i+1],B=hi[i+1],l,h;
    if(o.renorm){
      l=ceildiv(A-254,255); h=floordiv(B+1,255);
      if(l<0)l=0; if(h>o.R-1)h=o.R-1;
    } else {
      if(o.b==0){ l=A; h=B<o.split-1?B:o.split-1; }
      else { l=A+o.split; h=(B+o.split)<(o.R-1)?(B+o.split):(o.R-1); }
    }
    if(l<0)l=0;
    if(l>h){fprintf(stderr,"infeasible at op %d renorm=%d A=%d B=%d R=%d split=%d b=%d l=%d h=%d\n",i,o.renorm,A,B,o.R,o.split,o.b,l,h);return 2;}
    lo[i]=l; hi[i]=h;
  }

  unsigned char *out=malloc(N+16); int no=0;
  long long f=0;
  for(int i=0;i<N;i++){
    Op o=ops[i];
    if(o.renorm){
      if(f<lo[i]||f>hi[i]){fprintf(stderr,"fwd infeasible renorm %d f=%lld [%d,%d]\n",i,f,lo[i],hi[i]);return 3;}
      int A=lo[i+1],B=hi[i+1];
      int dl=(int)(A-255*f), dh=(int)(B-255*f);
      if(dl<-1)dl=-1; if(dh>254)dh=254;
      if(dl>dh){fprintf(stderr,"no digit at %d f=%lld A=%d B=%d\n",i,f,A,B);return 4;}
      int mid=(A+B)/2 - (int)(255*f);
      int d=mid; if(d<dl)d=dl; if(d>dh)d=dh;
      out[no++]=(unsigned char)(d+1);
      f=255*f+d;
    } else {
      if(o.b==0){ if(f>=o.split){fprintf(stderr,"bit0 fail %d\n",i);return 5;} }
      else { if(f<o.split){fprintf(stderr,"bit1 fail %d\n",i);return 6;} f-=o.split; }
    }
  }

  FILE*g=fopen(outf,"wb"); fwrite(out,1,no,g); fclose(g);
  fprintf(stderr,"data=%d tokens=%d ops=%d outbytes=%d\n",n,ntok,N,no);
  return 0;
}

