    }
  }

  FILE*g=fopen(outf,"wb"); fwrite(out,1,no,g); fclose(g);
  fprintf(stderr,"data=%d tokens=%d ops=%d outbytes=%d\n",n,ntok,N,no);
  return 0;
}

